{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.prepack_operations as with params as ( select convert_timezone(\'Asia/Kolkata\', current_timestamp())::date as as_of_date ), inventory_ranked as ( select upper(trim(\"Item SkuCode\")) as prepack_sku, trim(facility) as warehouse_name, \"Category Name\" as inventory_category, \"Item Type Name\" as prepack_definition, try_to_number(to_varchar(inventory)) as inventory_balance, try_to_number(to_varchar(\"Inventory Blocked\")) as inventory_blocked, try_to_number(to_varchar(\"Bad Inventory\")) as bad_inventory, try_to_number(to_varchar(\"Not Found\")) as not_found, try_to_number(to_varchar(\"Stock In Transfer\")) as stock_in_transfer, try_to_number(to_varchar(\"Open Purchase\")) as open_purchase, try_to_number(to_varchar(\"Open Sale\")) as open_sale, try_to_number(to_varchar(\"Putaway Pending\")) as inventory_putaway_pending, try_to_timestamp_ntz(to_varchar(updated)) as inventory_updated_at, row_number() over ( partition by upper(trim(\"Item SkuCode\")), trim(facility) order by try_to_timestamp_ntz(to_varchar(updated)) desc nulls last ) as row_num from snitch_db.maplemonk.unicommerce_live_inventory where \"Item SkuCode\" ilike \'PP%\' ), inventory as ( select * exclude row_num from inventory_ranked where row_num = 1 ), putaway_ranked as ( select upper(trim(\"Item Type skuCode\")) as prepack_sku, trim(\"Warehouse Name\") as warehouse_name, \"Putaway Item Id\" as putaway_item_id, \"Putaway Code\" as putaway_code, skugroup as prepack_sku_group, category as putaway_category, product_name as putaway_product_name, try_to_number(to_varchar(total_quantity)) as inward_total_qty, try_to_number(to_varchar(putaway_completed_quantity)) as inward_completed_qty, try_to_number(to_varchar(pending_qty)) as inward_pending_qty, try_to_timestamp_ntz(to_varchar(putaway_created)) as putaway_created_at, try_to_timestamp_ntz(to_varchar(putaway_updated)) as putaway_updated_at, try_to_date(to_varchar(putaway_completed_date)) as putaway_completed_date, row_number() over ( partition by \"Putaway Item Id\" order by try_to_timestamp_ntz(to_varchar(putaway_updated)) desc nulls last ) as row_num from snitch_db.maplemonk.putaway_tracking where \"Item Type skuCode\" ilike \'PP%\' and final_type = \'New Inward\' ), putaway as ( select prepack_sku, warehouse_name, max(prepack_sku_group) as prepack_sku_group, max(putaway_category) as putaway_category, max(putaway_product_name) as putaway_product_name, count(distinct putaway_item_id) as inward_record_count, count(distinct putaway_code) as putaway_count, sum(coalesce(inward_total_qty, 0)) as inward_total_qty, sum(coalesce(inward_completed_qty, 0)) as inward_completed_qty, sum(coalesce(inward_pending_qty, 0)) as inward_pending_qty, min(putaway_created_at) as first_inward_created_at, max(iff(inward_completed_qty > 0, putaway_completed_date, null)) as latest_inward_completed_date, max(putaway_updated_at) as latest_putaway_updated_at from putaway_ranked where row_num = 1 group by prepack_sku, warehouse_name ), orders_ranked as ( select upper(trim(sku)) as prepack_sku, trim(warehouse_name) as warehouse_name, sku_group as order_sku_group, category as order_category, order_id, saleorderitemcode, order_status, sale_order_item_status, try_to_number(to_varchar(suborder_quantity)) as ordered_qty, try_to_date(to_varchar(order_date)) as order_date, row_number() over ( partition by coalesce( nullif(trim(saleorderitemcode), \'\'), concat_ws(\'|\', trim(order_id), upper(trim(sku)), to_varchar(order_timestamp)) ) order by try_to_timestamp_ntz(to_varchar(shipping_last_update_timestamp)) desc nulls last, try_to_timestamp_ntz(to_varchar(order_timestamp)) desc nulls last ) as row_num from snitch_db.maplemonk.unicommerce_fact_items_intermediate where marketplace_mapped ilike \'%store%\' and sku ilike \'PP%\' ), orders as ( select prepack_sku, warehouse_name, max(order_sku_group) as order_sku_group, max(order_category) as order_category, count(distinct order_id) as b2b_retail_orders_placed, sum(coalesce(ordered_qty, 0)) as b2b_retail_order_qty, count(distinct iff( coalesce(upper(order_status), \'\') <> \'CANCELLED\' and coalesce(upper(sale_order_item_status), \'\') <> \'CANCELLED\', order_id, null )) as b2b_retail_non_cancelled_orders, sum(iff( coalesce(upper(order_status), \'\') <> \'CANCELLED\' and coalesce(upper(sale_order_item_status), \'\') <> \'CANCELLED\', coalesce(ordered_qty, 0), 0 )) as b2b_retail_non_cancelled_qty, sum(iff( upper(order_status) = \'CANCELLED\' or upper(sale_order_item_status) = \'CANCELLED\', coalesce(ordered_qty, 0), 0 )) as b2b_retail_cancelled_qty, min(order_date) as first_order_date, max(order_date) as latest_order_date from orders_ranked where row_num = 1 group by prepack_sku, warehouse_name ), prepack_warehouse_spine as ( select prepack_sku, warehouse_name from inventory union select prepack_sku, warehouse_name from putaway union select prepack_sku, warehouse_name from orders ), joined as ( select s.prepack_sku, s.warehouse_name, coalesce(p.prepack_sku_group, o.order_sku_group) as prepack_sku_group, coalesce(i.inventory_category, p.putaway_category, o.order_category) as category, coalesce(i.prepack_definition, p.putaway_product_name) as prepack_definition, coalesce(p.inward_record_count, 0) as inward_record_count, coalesce(p.putaway_count, 0) as putaway_count, coalesce(p.inward_total_qty, 0) as inward_total_qty, coalesce(p.inward_completed_qty, 0) as inward_completed_qty, coalesce(p.inward_pending_qty, 0) as inward_pending_qty, iff(coalesce(p.inward_completed_qty, 0) > 0, 1, 0) as distinct_prepack_units_inwarded, p.first_inward_created_at, p.latest_inward_completed_date, p.latest_putaway_updated_at, coalesce(o.b2b_retail_orders_placed, 0) as b2b_retail_orders_placed, coalesce(o.b2b_retail_order_qty, 0) as b2b_retail_order_qty, coalesce(o.b2b_retail_non_cancelled_orders, 0) as b2b_retail_non_cancelled_orders, coalesce(o.b2b_retail_non_cancelled_qty, 0) as b2b_retail_non_cancelled_qty, coalesce(o.b2b_retail_cancelled_qty, 0) as b2b_retail_cancelled_qty, o.first_order_date, o.latest_order_date, coalesce(i.inventory_balance, 0) as inventory_balance, coalesce(i.inventory_blocked, 0) as inventory_blocked, coalesce(i.bad_inventory, 0) as bad_inventory, coalesce(i.not_found, 0) as not_found, coalesce(i.stock_in_transfer, 0) as stock_in_transfer, coalesce(i.open_purchase, 0) as open_purchase, coalesce(i.open_sale, 0) as open_sale, coalesce(i.inventory_putaway_pending, 0) as inventory_putaway_pending, i.inventory_updated_at, cfg.as_of_date, iff( coalesce(i.inventory_balance, 0) > 0 and p.latest_inward_completed_date is not null, greatest(0, datediff(\'day\', p.latest_inward_completed_date, cfg.as_of_date)), null ) as inventory_age_days from prepack_warehouse_spine s cross join params cfg left join inventory i on i.prepack_sku = s.prepack_sku and i.warehouse_name = s.warehouse_name left join putaway p on p.prepack_sku = s.prepack_sku and p.warehouse_name = s.warehouse_name left join orders o on o.prepack_sku = s.prepack_sku and o.warehouse_name = s.warehouse_name ) select joined.*, case when inventory_balance <= 0 then \'NO_INVENTORY\' when latest_inward_completed_date is null then \'INWARD_DATE_MISSING\' when inventory_age_days > 7 then \'8+ DAYS\' when inventory_age_days >= 4 then \'4-7 DAYS\' else \'0-3 DAYS\' end as inventory_age_bucket, inventory_balance > 0 and inventory_age_days > 7 as inventory_aging_red_flag from joined;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

